head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.POPUP_URL_PREEXAM = "/ui/lst/kindstk/ULDSTF05101.xml";   // 종류주식 예비심사관리 팝업 (원본 리터럴)
scwin.POPUP_URL_ISU = "/ui/lst/kindstk/ULDSTF05107.xml";       // 종류주식 예비심사 종목선택 팝업 (원본 리터럴)
scwin.MKT_TP_KSE = "1";       // 유가증권시장
scwin.MKT_TP_KOSDAQ = "2";    // 코스닥시장

// 원본 : /kindstk/ULDSTF05100.gfm (예비심사 — 종류주식) — W-Craft 1차 변환 + API 적용 개발 사본(ui/ULDSTF05100/ULDSTF05100.xml)
/*
 * 화면 동작
 *  - 조회조건(증권구분·청구접수일/상장일 기간·법인·상장구분·시장구분·종목·상장주선인)으로 종류주식 예비심사 목록을 조회한다.
 *  - 행을 더블클릭하면 그 건, [신규]는 아래 [유가증권]에서 고른 증권구분으로 예비심사관리 팝업(ULDSTF05101)을 연다.
 *    팝업이 저장하고 닫히거나 창 닫기(X)로 닫히면 목록을 다시 조회하고 연 행을 다시 선택한다.
 *  - [법인 찾기]는 법인선택(ULDSTF05011), [종목 찾기]는 예비심사 종목선택(ULDSTF05107) 팝업이다.
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05100/ULDSTF05100.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 기간 콤보·기본 기간 → 기간 달력·조회 Enter 키 바인딩 → 시장 사용자 시장구분 고정 → 상장주선인 콤보 → 목록 조회. (원본 gform_onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 기간선택 콤보와 기본 기간(시작 19000101 ~ 종료 오늘+60일) — 원본 comboCbDataSetPeriod + 시작·종료 직접 설정
    $c.data.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.lc.initSearchDate(edt_SDate, edt_EDate);

    // 2) 기간 달력 선후 검사(규칙 37)·조회 영역 Enter 키(규칙 22)
    $c.date.compareFromToDate(edt_SDate, edt_EDate, ["조회 시작일", "조회 종료일"]);
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);

    // 3) 유가·코스닥 시장 사용자는 자기 시장으로 고정하고 시장구분을 숨긴다 (원본 주석의 js_market 분기 — 05102 와 같게, §8 #6)
    const userMarket = $c.session.getUserInfo("market");
    if (userMarket === scwin.MKT_TP_KSE || userMarket === scwin.MKT_TP_KOSDAQ) {
        rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue(userMarket);
        panel_mkt_gubun.hide();
    }

    // 4) 상장주선인 콤보를 채운 뒤 조회 (원본 순서)
    await scwin.selectLeadcomList();
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_CoCdSearch_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_CoCdSearch_onclick = async function (e) {
    try {
        await scwin.openCorpPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.btn_CoCdSearch_onclick" });
    }
};

/**
 * @method
 * @name scwin.txb_ISUR_CD_onblur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인코드 칸을 비우고 나가면 법인명도 비운다. (원본 txb_ISUR_CD_onblur)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function (e) {
    try {
        if ($c.util.isEmpty(txb_ISUR_CD.getValue())) {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05100.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name scwin.btn_ISU_CD_SEARCH_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_ISU_CD_SEARCH_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.btn_ISU_CD_SEARCH_onclick" });
    }
};

/**
 * @method
 * @name scwin.cmb_PeriodTp_onviewchange
 * @author Inswave
 * @date 2026. 10. 29
 * @description 기간선택 — 고른 기간으로 시작·종료일을 채운다(종료일 기준 역산, 종료일이 비면 오늘). (원본 cmb_PeriodTp_OnSelChange)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_PeriodTp_onviewchange = function (info) {
    try {
        // 콤보 값(0~6)은 index 와 같고, 공통 함수는 숫자로 비교한다(문자열 값을 넘기면 어느 기간에도 맞지 않는다 — §8 #8)
        $c.stf.setFromToDate(cmb_PeriodTp.getSelectedIndex(), edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05100.cmb_PeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록 행 더블클릭 — 그 건으로 예비심사관리 팝업을 연다. (원본 grd_List_oncelldblclick → fn_OpenDetail(row, 'U'))
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.openDetail(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 엑셀다운로드 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Excel_onclick = async function (e) {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 버튼 클릭 — [유가증권]을 골랐으면 신규로 예비심사관리 팝업을 연다. (원본 btn_New_onclick → fn_OpenDetail(-999))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_New_onclick = async function (e) {
    try {
        await scwin.openNew();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05100.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectLeadcomList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장주선인 콤보 목록 조회 — 콤보는 itemset 으로 dlt_codeSelectBox 에 바인딩돼 있다. (원본 fn_set_code — §5.1)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectLeadcomList = async function () {
    const sbmOptions = {
        id : "sbm_listLeadcomAll",
        method : "get",
        action : "/api/listing/common/code/list-leadcom-all",
        target : "dlt_codeSelectBox=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    return result.responseJSON?.success === true;    // 실패 안내는 공통 오류 핸들러
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사 목록 조회 — 조회조건은 dma_search 에 바인딩돼 있고, 상장구분 코드·index 만 콤보에서 꺼내 넣는다. 건수를 적는다. (원본 fn_list_sync — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    // 상장구분은 "전체"·"상장 - 전체" 두 항목이 같은 값("")이라 서버가 index 로 구분한다 — ref 로 묶지 않고 조회 때 꺼낸다(§2.1, §8 #3)
    dma_search.set("listLmCd", cmb_ListLMCd.getValue());
    dma_search.set("listLmCdIdx", String(cmb_ListLMCd.getSelectedIndex()));

    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/kind/prelisting-kindstk/select-list",
        ref : "dma_search",
        target : "dlt_List=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;    // 실패 안내는 공통 오류 핸들러(원본 OnLoadError → alert_error)

    spn_page.setValue(dlt_List.getRowCount());
    return true;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.openNew
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 — [유가증권](증권구분)을 고르지 않았으면 안내하고 멈춘다. (원본 btn_New_onclick — §6.1)
 * @returns
 * @hidden N
 */
scwin.openNew = async function () {
    if ($c.util.isEmpty(cmb_NEW_SECUGRP_ID.getValue())) {
        await $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
        cmb_NEW_SECUGRP_ID.focus();
        return;
    }
    await scwin.openDetail(-1);
};

/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 예비심사관리 팝업(ULDSTF05101)을 data 로 열고 닫힐 때까지 기다린다. 팝업이 저장하고 닫혔거나(isSaved) 창 닫기(X)로 닫혔으면
 * 목록을 다시 조회하고 연 행을 다시 선택한다. 키는 kindstk 공통 계약(05101 절). (원본 fn_OpenDetail + 팝업의 부모 전역 직접 참조·fn_list_sync — §6.2, 가이드 §6.5)
 * @param {Number} rowIndex 목록 행 인덱스(화면 번호). 신규는 -1
 * @returns
 * @hidden N
 */
scwin.openDetail = async function (rowIndex) {
    let bzProcsNo = "";
    let listBzSeq = "";
    let secugrpId = "";

    if (rowIndex >= 0) {
        bzProcsNo = String(dlt_List.getCellData(rowIndex, "bzProcsNo") ?? "");
        listBzSeq = String(dlt_List.getCellData(rowIndex, "listBzSeq") ?? "");
        secugrpId = String(dlt_List.getCellData(rowIndex, "secugrpId") ?? "");
    } else {
        secugrpId = cmb_NEW_SECUGRP_ID.getValue();
    }

    const data = {
        bzProcsNo : bzProcsNo,                                  // 원본 parentWin.scwin.clickBzProcsNo (신규 "")
        listBzSeq : listBzSeq,                                  // 원본 parentWin.scwin.clickListBzSeq (신규 "")
        mktTpCd : rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue(),       // 원본 parentWin.rdo_SPOT_ISU_TRD_MKT_TP_CD
        newSecugrpId : cmb_NEW_SECUGRP_ID.getValue()            // 원본 parentWin.cmb_NEW_SECUGRP_ID — 신규 증권그룹 기본값
    };
    // 원본 높이 분기(DR·FS 830 / 그 밖 750)는 쓰지 않던 변수 — 계약 크기 1400×1500 (§8 #9)
    const res = await $c.win.openPopup(scwin.POPUP_URL_PREEXAM,
        { id : "ULDSTF05101", popupName : $c.lc.getSecuGrpNm(secugrpId) + " 종류주식 예비심사관리", width : 1400, height : 1500, frameModal : "top" }, data);

    // 저장하고 닫힘 또는 창 닫기(X — 저장 여부를 모르므로 다시 조회) — kindstk 재조회 규약
    if (res?.isSaved !== true && res?.isCloseButtonClick !== true) return;
    if (!await scwin.selectList()) return;
    scwin.restoreRow(bzProcsNo, listBzSeq, rowIndex);
};

/**
 * @method
 * @name scwin.restoreRow
 * @author Inswave
 * @date 2026. 10. 29
 * @description 다시 조회한 목록에서 팝업을 연 행을 다시 선택한다 — 업무처리번호·상장업무일련번호가 같은 행, 없으면 원래 행 번호. 신규는 선택하지 않는다.
 * (원본 팝업의 parentWin.grd_*.setFocusedCell(rowPos) — kindstk 공통 계약 「행 포커스 복원은 부모가」, §6.2)
 * @param {String} bzProcsNo 업무처리번호 (신규 "")
 * @param {String} listBzSeq 상장업무일련번호 (신규 "")
 * @param {Number} rowIndex 팝업을 열 때의 행 인덱스 (신규 -1)
 * @returns
 * @hidden N
 */
scwin.restoreRow = function (bzProcsNo, listBzSeq, rowIndex) {
    const rowCount = dlt_List.getRowCount();
    if (rowIndex < 0 || rowCount === 0) return;

    let focusRow = -1;
    for (let i = 0; i < rowCount; i++) {
        if (String(dlt_List.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo
            && String(dlt_List.getCellData(i, "listBzSeq") ?? "") === listBzSeq) {
            focusRow = i;
            break;
        }
    }
    if (focusRow < 0 && rowIndex < rowCount) focusRow = rowIndex;
    if (focusRow >= 0) grd_List.setFocusedCell(focusRow, 0);
};

/**
 * @method
 * @name scwin.openCorpPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 법인 찾기 — 법인선택(ULDSTF05011)에서 고른 법인을 조회조건에 넣는다. 취소·창 닫기면 아무것도 하지 않는다.
 * (원본 btn_CoCdSearch_onclick + fn_GetPar/fn_SetPar — §6.3)
 * @returns
 * @hidden N
 */
scwin.openCorpPopup = async function () {
    // pcc 는 증권그룹ID 하나만 넘긴다. 반환은 05011 목록 행(camelCase), 취소·X 는 { isCloseButtonClick } 이라 법인코드로 판정
    const res = await $c.lc.popFindExamCorp(rdo_SECUGRP_ID.getValue());
    if ($c.util.isEmpty(res?.isurCd)) return;

    txb_ISUR_CD.setValue(String(res.isurCd));
    txb_COM_NM.setValue(String(res.comNm ?? ""));
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기 — 예비심사 종목선택(ULDSTF05107)을 data 로 열고, 고른 종목을 조회조건에 넣는다. 취소·창 닫기면 아무것도 하지 않는다.
 * 키는 kindstk 공통 계약(05107 절). (원본 fn_PopFindKindStkExamIsu + fn_GetParForIsuCd/fn_SetParForIsuCd — §6.4, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const data = {
        isurCd : txb_ISUR_CD.getValue(),                            // 원본 05107 이 부모 컴포넌트를 직접 읽던 회사코드 — 05100 에는 그 칸이 없어 오류였다(§8 #4)
        secugrpId : rdo_SECUGRP_ID.getValue(),
        mktTpCd : rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue(),
        searchType : $c.lc.getGlbValue("SEARCH_TYP_SER")            // 유가예비심사등록조회
    };
    const res = await $c.win.openPopup(scwin.POPUP_URL_ISU,
        { id : "ULDSTF05107", popupName : "종류주식 예비심사 종목 선택", width : 800, height : 780, frameModal : "top", type : "pageFramePopup" }, data);
    if ($c.util.isEmpty(res?.isuCd)) return;

    // 원본은 반환값을 버렸다(TODO) — fn_SetParForIsuCd 의 의도대로 종목코드·종목명에 넣는다(§8 #5)
    txb_ISU_CD.setValue(String(res.isuCd));
    txb_ISU_NM.setValue(String(res.isuNm ?? ""));
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록을 엑셀로 내려받는다. 0건이면 안내한다. (원본 fn_ExcelDown — §6.5)
 * @returns
 * @hidden N
 */
scwin.excelDown = async function () {
    if (dlt_List.getRowCount() === 0) {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_List, {
        // 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (전환 규칙 42)
        fileName : $c.win.getProgramId() + "_예비심사_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx",
        sheetName : "sheet1"
    });
};

/**
 * @method
 * @name scwin.fmtInvstgBillAcptDd
 * @author Inswave
 * @date 2026. 10. 29
 * @description 청구서접수일 표시 — 8자리면 날짜, 14자리 이상이면 일시로 표시한다(같은 열에 두 길이가 섞여 온다). (원본 invstgBillAcptDd_customFormatter — 규칙 43, §2.2)
 * @param {String} data 셀 값
 * @param {String} formattedData 형식 적용 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {String} 표시 값
 * @hidden N
 */
scwin.fmtInvstgBillAcptDd = function (data, formattedData, rowIndex, columnIndex) {
    const value = String(data ?? "");
    if (value.length === 8) return $c.date.dateFormat(value, "yyyy-MM-dd");
    if (value.length >= 14) return $c.date.dateFormat(value, "yyyy-MM-dd HH:mm:ss");
    return value;
};
